def next_smallest_palindrome(n: int) -> int:
    s = str(n + 1)  # start checking from the next integer
    length = len(s)

    while True:
        if s == s[::-1]:
            return int(s)
        # Generate palindrome by mirroring left half to right half
        half = (length + 1) // 2
        left = s[:half]
        if length % 2 == 0:
            pal = left + left[::-1]
        else:
            pal = left + left[:-1][::-1]

        if int(pal) >= int(s):
            s = pal
        else:
            # increment the left half and rebuild palindrome
            left_num = str(int(left) + 1)
            # Handle length increase after increment (e.g., 99 -> 100)
            if len(left_num) > len(left):
                length += 1
                s = '1' + ('0' * (length - 1))
            else:
                if length % 2 == 0:
                    s = left_num + left_num[::-1]
                else:
                    s = left_num + left_num[:-1][::-1]

